import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 세율 10%. 국세청 연계 정보가 입력에 없어 내부 자료의 세액 정합성으로 대사한다.
const ASSUMED_TAX_RATE = 0.1;
const ROLE = '예산·회계 담당자';

@Controller('api/v1')
export class FnSfr00803Controller {
  @Post('/tax-invoices/:taxInvoiceId/verify')
  @HttpCode(200)
  async verifyTaxInvoice(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const taxInvoiceId = req.params['taxInvoiceId'];
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT tax_type AS "taxType",
                supply_amount AS "supplyAmount",
                tax_amount AS "taxAmount"
           FROM tax_invoice
          WHERE tax_invoice_id = CAST(:id AS bigint)
          FOR UPDATE`,
        { id: taxInvoiceId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'TAX_INVOICE_NOT_FOUND', '대상 전자세금계산서가 없습니다.');
      }
      const row = rows[0];
      // TODO(질문): 국세청 연계 정보 조회·비교 (NTS_LINK_FAILED 처리 포함). 가정: 내부 세액 정합성으로 대체
      let mismatchReason = '';
      if (row.taxType === '면세') {
        if (Number(row.taxAmount) !== 0) {
          mismatchReason = '면세 건의 세액이 0이 아닙니다.';
        }
      } else {
        const expected = Math.round(Number(row.supplyAmount) * ASSUMED_TAX_RATE);
        if (Number(row.taxAmount) !== expected) {
          mismatchReason = '세액이 공급가액 기준 세액과 다릅니다.';
        }
      }
      const matched = mismatchReason === '';
      const reconciliationResult = matched ? '일치' : '불일치';
      await db.execute(
        `UPDATE tax_invoice
            SET reconciliation_result = :result,
                verified = :verified,
                updated_at = now()
          WHERE tax_invoice_id = CAST(:id AS bigint)`,
        { result: reconciliationResult, verified: matched, id: taxInvoiceId },
      );
      return { reconciliationResult, verified: matched, mismatchReason };
    });
  }

  @Post('/tax-invoices/:taxInvoiceId/process-voucher')
  @HttpCode(200)
  async processTaxInvoiceVoucher(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const taxInvoiceId = req.params['taxInvoiceId'];
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT journal_voucher_id AS "journalVoucherId",
                expense_resolution_id AS "expenseResolutionId",
                verified,
                reconciliation_result AS "reconciliationResult",
                supply_amount AS "supplyAmount",
                tax_amount AS "taxAmount"
           FROM tax_invoice
          WHERE tax_invoice_id = CAST(:id AS bigint)
          FOR UPDATE`,
        { id: taxInvoiceId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'TAX_INVOICE_NOT_FOUND', '대상 전자세금계산서가 없습니다.');
      }
      const row = rows[0];
      if (row.journalVoucherId !== null && row.journalVoucherId !== undefined) {
        throw new ApiError(409, 'TAX_INVOICE_ALREADY_PROCESSED', '이미 전표처리된 전자세금계산서입니다.');
      }
      if (row.verified !== true || row.reconciliationResult !== '일치') {
        throw new ApiError(422, 'TAX_INVOICE_NOT_VERIFIED', '검증을 통과하지 못했거나 불일치한 전자세금계산서는 전표처리할 수 없습니다.');
      }
      // 가정: 차변·대변 합계는 공급가액 + 세액
      const total = Number(row.supplyAmount) + Number(row.taxAmount);
      const created = await db.query(
        `INSERT INTO journal_voucher
           (expense_resolution_id, voucher_date, evidence_type, source_type, status,
            debit_total, credit_total, created_at, updated_at)
         VALUES
           (CAST(:resolutionId AS bigint), CAST(now() AS date), '전자세금계산서', 'AUTO', '승인',
            CAST(:total AS numeric), CAST(:total AS numeric), now(), now())
         RETURNING journal_voucher_id AS "journalVoucherId"`,
        { resolutionId: row.expenseResolutionId, total: String(total) },
      );
      const journalVoucherId = created[0].journalVoucherId;
      await db.execute(
        `UPDATE tax_invoice
            SET journal_voucher_id = CAST(:voucherId AS bigint),
                updated_at = now()
          WHERE tax_invoice_id = CAST(:id AS bigint)`,
        { voucherId: journalVoucherId, id: taxInvoiceId },
      );
      return { journalVoucherId };
    });
  }

  @Get('/tax-invoices/:taxInvoiceId/print')
  async printTaxInvoice(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const taxInvoiceId = req.params['taxInvoiceId'];
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT t.approval_no AS "approvalNo",
                p.partner_name AS "partnerName",
                t.direction AS "direction",
                t.tax_type AS "taxType",
                CAST(t.issue_date AS text) AS "issueDate",
                t.supply_amount AS "supplyAmount",
                t.tax_amount AS "taxAmount"
           FROM tax_invoice t
           JOIN partner p ON p.partner_id = t.partner_id
          WHERE t.tax_invoice_id = CAST(:id AS bigint)`,
        { id: taxInvoiceId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'TAX_INVOICE_NOT_FOUND', '대상 전자세금계산서가 없습니다.');
      }
      const r = rows[0];
      // 가정: 출력 형식은 항목별 텍스트
      const printFile = [
        '전자세금계산서',
        '승인번호: ' + r.approvalNo,
        '거래처: ' + r.partnerName,
        '구분: ' + r.direction + ' / ' + r.taxType,
        '작성일자: ' + r.issueDate,
        '공급가액: ' + r.supplyAmount,
        '세액: ' + r.taxAmount,
      ].join('\n');
      return { printFile };
    });
  }
}

