import { useState } from 'react';
import type { ReactNode } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  DateInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

type Action = { kind: 'verify' | 'voucher' | 'print'; row: Row };

function PrintPanel({ id, role }: { id: unknown; role: string }) {
  const { data, error, loading } = useData<Row>(
    () => call('GET', `/tax-invoices/${id}/print`, role),
    [id],
  );
  if (loading) return <p>불러오는 중…</p>;
  if (error) return <ErrorText text={error} />;
  return <pre>{String(data?.printFile ?? '')}</pre>;
}

export default function FnSfr00803Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [action, setAction] = useState<Action | null>(null);
  const [result, setResult] = useState<Row | null>(null);
  const [log, setLog] = useState<Row[]>([]);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/tax-invoices', role, undefined, { ...applied, page, size: 20 }),
    [applied, page],
  );
  const rows = data?.items ?? [];
  const supplySum = rows.reduce((s, r) => s + Number(r.supplyAmount ?? 0), 0);
  const taxSum = rows.reduce((s, r) => s + Number(r.taxAmount ?? 0), 0);

  function open(kind: Action['kind'], row: Row) {
    setResult(null);
    setAction({ kind, row });
  }

  function search() {
    setPage(0);
    setApplied({ startDate, endDate, partnerId });
  }

  function reset() {
    setStartDate('');
    setEndDate('');
    setPartnerId('');
    setPage(0);
    setApplied({});
  }

  function addLog(row: Row, text: string) {
    setLog((prev) => [{ n: prev.length + 1, approvalNo: row.approvalNo, text }, ...prev].slice(0, 10));
  }

  async function verify(row: Row) {
    const r = await call<Row>('POST', `/tax-invoices/${row.taxInvoiceId}/verify`, role, {});
    setResult(r);
    addLog(row, '검증 ' + String(r.reconciliationResult));
    notify('검증했습니다.');
    reload();
  }

  async function processVoucher(row: Row) {
    const r = await call<Row>('POST', `/tax-invoices/${row.taxInvoiceId}/process-voucher`, role, {});
    setResult(r);
    addLog(row, '전표처리 완료 (전표 ' + String(r.journalVoucherId) + ')');
    notify('전표처리했습니다.');
    reload();
  }

  let drawer: ReactNode = null;
  if (action) {
    const row = action.row;
    const head: [string, ReactNode][] = [
      ['승인번호', String(row.approvalNo)],
      ['거래처 ID', <RefName table="partner" role={role} value={row.partnerId} />],
      ['공급가액', <Num value={row.supplyAmount} />],
      ['세액', <Num value={row.taxAmount} />],
    ];
    if (action.kind === 'verify') {
      drawer = (
        <Drawer title="전자세금계산서 검증" onClose={() => setAction(null)}>
          <Pairs items={head} />
          <Form submit="검증 실행" onSubmit={() => verify(row)} note="국세청 정보와 비교해 대사 결과를 저장합니다.">
            {result ? (
              <Pairs
                items={[
                  ['대사 결과', <Badge value={result.reconciliationResult} />],
                  ['검증 여부', result.verified ? '검증됨' : '검증 안 됨'],
                  ['불일치 사유', String(result.mismatchReason || '-')],
                ]}
              />
            ) : null}
          </Form>
        </Drawer>
      );
    } else if (action.kind === 'voucher') {
      drawer = (
        <Drawer title="전표처리" onClose={() => setAction(null)}>
          <Pairs items={head} />
          <Form submit="전표처리" onSubmit={() => processVoucher(row)} note="검증을 통과한 건만 전표처리할 수 있습니다. 증빙 유형은 전자세금계산서입니다.">
            {result ? <Pairs items={[['전표 ID', String(result.journalVoucherId)]]} /> : null}
          </Form>
        </Drawer>
      );
    } else {
      drawer = (
        <Drawer title="전자세금계산서 출력" onClose={() => setAction(null)}>
          <PrintPanel id={row.taxInvoiceId} role={role} />
        </Drawer>
      );
    }
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={data?.total ?? 0} />],
            ['공급가액 (현재 쪽)', <Num value={supplySum} />],
            ['세액 (현재 쪽)', <Num value={taxSum} />],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>발행·수취 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="발행일 시작">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="발행일 종료">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="거래처 ID">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} placeholder="전체" />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total} />
        <DataTable
          rows={rows}
          empty="전자세금계산서가 없습니다."
          columns={[
            { key: 'approvalNo', label: '승인번호' },
            { key: 'partnerId', label: '거래처 ID', render: (r) => <RefName table="partner" role={role} value={r.partnerId} /> },
            { key: 'direction', label: '매출/매입 구분', render: (r) => <Badge value={r.direction} /> },
            { key: 'taxType', label: '과세·면세 구분' },
            { key: 'issueDate', label: '작성일자', render: (r) => <DateText value={r.issueDate} /> },
            { key: 'supplyAmount', label: '공급가액', render: (r) => <Num value={r.supplyAmount} /> },
            { key: 'taxAmount', label: '세액', render: (r) => <Num value={r.taxAmount} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <span>
                  <button type="button" onClick={() => open('verify', r)}>검증</button>
                  <button type="button" onClick={() => open('voucher', r)}>전표처리</button>
                  <button type="button" onClick={() => open('print', r)}>출력</button>
                </span>
              ),
            },
          ]}
        />
        <Pager page={data?.page ?? 0} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>최근 처리</h2>
        <DataTable
          rows={log}
          empty="처리한 내역이 없습니다."
          columns={[
            { key: 'approvalNo', label: '승인번호' },
            { key: 'text', label: '처리 결과' },
          ]}
        />
      </section>
      {drawer}
    </div>
  );
}
